/**
 * Bài 29 — 健康 (Sức khoẻ) · TIẾP SAU SÁCH, cấp N3 (xem ../SOAN-BAI.md mục 8). Bài thứ tư của chặng 26–30
 * (Bài 30 = kiểm tra chặng).
 * Người học đã xong Bài 1–15 (ポイント 1–124 — trong đó ～ぐらい "khoảng" (ポイント 30), ～ほうがいい (105), ～し (Bài 17 ③)),
 * Bài 16–24 (thể khả năng / ý chí, ば・なら・たら — Bài 17 có mục "biết trước" ～ば～ほど, ～すぎる, ～てしまう, ～ようになる,
 * bị động, sai khiến, kính ngữ), Bài 25 (ôn N4), Bài 26 (～うちに, ～間・間に, ～最中に, ～たとたん), Bài 27 (～せいで, ～おかげで,
 * ～によって, ～ため) và Bài 28 (～くせに, ～ものの, ～にもかかわらず, ～に対して). KHÔNG dạy lại — chỉ dùng lại trong câu
 * (ghi "ôn: Bài X").
 *
 * Ngữ pháp (N3) — nhóm "MỨC ĐỘ – SO SÁNH – ĐIỀU KIỆN TỐI THIỂU – THÊM VÀO": ① ～ほど "đến mức…" (Vる／Vない／イA／ナAな／N ＋ ほど;
 * + số lượng ＋ ほど "khoảng") · ② N1 は N2 ほど～ない "không… bằng" · 思ったほど／それほど～ない · ～ほどではない "chưa đến mức" ·
 * ③ ～ほど～はない "không gì… bằng" · ④ ～くらい・ぐらい "đến mức" (≈ ほど, văn nói) + ～くらい～はない · ⑤ ～くらい・ぐらい "chỉ…
 * thôi mà / ít nhất cũng…" (xem nhẹ — ほど KHÔNG thay được) · ⑥ ～ば～ほど "càng… càng…" (V／イA／ナAなら～なほど, + rút gọn
 * ～ほど) · ⑦ ～さえ～ば "chỉ cần… là" (Nさえ～ば · Vますさえすれば · Vてさえいれば · イAくさえあれば · ナA／Nでさえあれば) + Nさえ
 * "ngay cả" · ⑧ ～うえ（に）"không những… mà còn…" (cùng chiều tốt–tốt / xấu–xấu; vế sau không ra lệnh / rủ / nhờ) · ⑨ BẢNG
 * PHÂN BIỆT: ほど ↔ くらい · ば～ほど ↔ につれて (Bài 32 dạy, ở đây chỉ nhắc) · さえ ↔ だけ ↔ しか · うえに ↔ し ↔ だけでなく ↔
 * しかも・その上 + chỉ cần NHẬN RA: ～くらいなら (N2), ～上で (N2).
 * Từ vựng: 64 từ (N3 là chính, một số N2 có ghi cấp): cơ thể & triệu chứng, khám bệnh, ăn uống & dinh dưỡng, vận động, lối sống &
 * mức độ — kèm bảng TỪ DỄ NHẦM (類義語) và KẾT HỢP TỪ (コロケーション). Từ đã học ở Bài 1–28 (病気, けが, 熱, のど, 調子, 食欲,
 * 睡眠, 薬, 薬局, 保険証, 治る, 入院する, 風邪, 健康, 体重, ダイエットする, 早寝早起き, 夜ふかしする, 禁煙する, 運動不足,
 * 太る, やせる, 具合, 気分, 寝不足, 好き嫌い, 規則, 習慣, 生活, 無理, 防ぐ, 調査…) KHÔNG lặp lại.
 * Chữ Hán mới (22): 程 首 退 呼 適 普 腹 煙 貧 抜 更 良 血 骨 胃 汗 検 査 栄 養 診 防 (12 chữ đầu N3 theo các bảng tham khảo phổ
 * biến; 10 chữ sau của chủ đề y tế — các bảng xếp N3 hoặc N2, ghi "N2–N3" — JLPT không công bố danh sách chữ chính thức) — không
 * trùng hanTu.ts, hanTu16–26.ts, hanLop.ts, bảng chữ Hán Bài 1–27 (Bài 27: 原 因 影 響 政 民 件 状 候 速 路 価 値 法 種 類 告 和 戦
 * 争) và Bài 28 (賛 議 判 断 否 認 疑 得 納 責 任 態 協 述 示 個 的 満 感 比 — vì thế 満 của {満腹|まんぷく} KHÔNG dạy lại; chữ của
 * bài này là 普 của {普段|ふだん}). Thẻ chữ Hán: hanTu29.ts (HAN_TU_29).
 * Hội thoại, câu ví dụ, bài đọc, kịch bản nghe: VIẾT MỚI 100%, không chép giáo trình/đề thi nào.
 *
 * Nhân vật (giới tính quyết định giọng đọc, theo sách p.14): nữ = パク, ワン, アンナ, メアリー, マリヤム, 山口, 木村, リン, 鈴木,
 * {佐藤先生|さとうせんせい} · nam = マルコ, ダニエル, ナタポン, カルロス, 西川, 本田先生, 小林店長.
 * Nối tiếp Bài 26–27: リン (năm nhất khoa Kinh tế trường {みなと大学|みなとだいがく}, ở {国際寮|こくさいりょう}), マリヤム (năm hai, cùng
 * ký túc xá), ダニエル (hay thức trắng đêm viết báo cáo — Bài 26 ②), カルロス (đá bóng, tập gym), アンナ, ナタポン (cao học, làm thêm
 * ở ひまわり食堂 của anh 小林).
 * Hội thoại: role 'a'/'c' = giọng nữ, 'b'/'examiner' = giọng nam. Nghe: 'ja-nu' = nữ, 'ja-nam' = nam.
 * Người MỚI của bài này:
 *  - {保健|ほけん}センターの{先生|せんせい} — nữ, bác sĩ ở trạm y tế của trường (hội thoại ①: role 'c'; nghe: ja-nu).
 *  - {受付|うけつけ}の{人|ひと} (nghe Bài 1 — lễ tân bệnh viện) — nữ, ja-nu · ジムのトレーナー (nghe Bài 2) — nam, ja-nam.
 * Hình: tên trong scripts/hinh/fluent-catalog.json (Fluent Emoji).
 */
import type { Block, Ex, Lesson } from '@/components/sach-hoc/types';

const E = (en: string, ro: string, vi: string): Ex => ({ en, ro, vi });

/**
 * Đáp án gõ tay: viết một lần bằng {漢字|かな}, hàm sinh đủ cách viết chữ Hán / kana
 * (máy chấm đã tự bỏ dấu câu, dấu cách và đổi chữ số toàn khổ). Phần tử đầu = dạng
 * toàn chữ Hán, là đáp án hiển thị.
 */
const V = (...xs: string[]): string[] => {
  const out = new Set<string>();
  for (const x of xs) {
    const slots = x
      .split(/(\{[^|}]+\|[^}]+\})/)
      .filter(Boolean)
      .map((p) => {
        const m = /^\{([^|}]+)\|([^}]+)\}$/.exec(p);
        return m ? [m[1], m[2]] : [p];
      });
    const n = slots.filter((s) => s.length > 1).length;
    if (n <= 8) {
      let acc = [''];
      for (const s of slots) acc = acc.flatMap((a) => s.map((c) => a + c));
      acc.forEach((a) => out.add(a));
    } else {
      out.add(slots.map((s) => s[0]).join(''));
      out.add(slots.map((s) => s[s.length - 1]).join(''));
      slots.forEach((s, i) => {
        if (s.length > 1) out.add(slots.map((t, j) => (j === i ? t[1] : t[0])).join(''));
      });
    }
  }
  return [...out];
};

type Line = [who: string, role: 'a' | 'b' | 'c' | 'examiner' | 'candidate', text: string, ro: string, vi: string];
const DL = (title: string, lines: Line[]): Block => ({
  t: 'dialogue',
  title,
  lines: lines.map(([who, role, text, ro, vi]) => ({ who, role, text, ro, vi })),
});

